function openSettings(){closeTools();showView("settings");}
async function loadConnections(){const host=$("[data-operations-connections]"),message=$("[data-settings-message]");if(!host)return;host.innerHTML='<div class="settings-loading"><i></i><span>Checking your connections…</span></div>';if(message)message.textContent="";let result;try{result=await transport("connections");}catch(error){result={ok:false,error:String(error)};}if(!result?.ok){host.innerHTML='<div class="settings-empty">Connections could not be checked.</div>';if(message)message.textContent=result?.error||"";return;}state.connections=result.connections||[];host.innerHTML=state.connections.map(connectionCard).join("");$$('[data-connection-action]',host).forEach(button=>button.addEventListener("click",()=>runConnectionAction(button)));}
function serviceIcon(provider,fallback=""){const src={trello:"../web_shared/trello.png",companycam:"../web_shared/companycam.png",xa:"../web_shared/xactanalysis.png"}[provider];return src?`<img class="service-icon" src="${src}" width="18" height="18" alt="">`:esc(fallback);}
function connectionCard(card){const button=card.action?`<button class="quiet-button ${card.state==="connected"?"":"connection-primary"}" data-provider="${attr(card.provider)}" data-connection-action="${attr(card.action)}">${esc(card.action_label)}</button>`:"";return `<article class="operations-connection" data-state="${attr(card.state)}"><span class="operations-connection-mark">${serviceIcon(card.provider,card.icon)}</span><div><header><strong>${esc(card.name)}</strong><b>${esc(card.status)}</b></header><p>${esc(card.detail)}</p>${card.identity?`<small>${esc(card.identity)}</small>`:""}${button}</div></article>`;}
async function runConnectionAction(button){const action=button.dataset.connectionAction,provider=button.dataset.provider;if(action==="sign_in"){openAccountModal();return;}if(action==="sign_out"){button.disabled=true;const result=await transport("account_sign_out");toast(result?.ok?result.message:(result?.error||"Could not sign out"));await loadConnections();return;}if(action==="admin_setup"){launchTool("settings_web",button);return;}const label=button.textContent;button.disabled=true;button.textContent=action==="connect_trello"?"Waiting for sign in…":"Opening…";const result=await transport("begin_connection",provider);button.disabled=false;button.textContent=label;if(result?.url)desktopAction("open_url",result.url);toast(result?.ok?(result.message||"Opened"):(result?.error||"Could not connect"));if(result?.ok)await loadConnections();}
function openAccountModal(){$("[data-account-modal]").hidden=false;setTimeout(()=>$("[data-account-form] input[name='email']")?.focus(),0);}
function closeAccountModal(){$("[data-account-modal]").hidden=true;$("[data-account-error]").textContent="";}
async function submitAccountSignIn(event){event.preventDefault();const form=event.currentTarget,submit=$("button[type='submit']",form),error=$("[data-account-error]",form),values=new FormData(form);submit.disabled=true;submit.textContent="Signing in…";error.textContent="";const result=await transport("account_sign_in",String(values.get("email")||""),String(values.get("password")||""));submit.disabled=false;submit.textContent="Sign in";if(!result?.ok){error.textContent=result?.error||"Sign in failed";form.elements.password.select();return;}form.reset();closeAccountModal();toast(result.message||"Signed in");await loadConnections();boot(true);}
function openJob(id){const job=state.data.jobs.find(j=>j.card_id===id);if(!job)return;state.selectedJob=job;state.jobContext=null;renderJobDrawer(job);loadJobContext(job);}
function renderJobDrawer(job,context=state.jobContext){
  const drawer=$("[data-job-drawer]"),progress=context?.progress||{},counts=progress.counts||{},fields=context?.fields||[];
  const copyFields=fields.length?fields:[{id:"job_name",label:"Job name",value:job.client}];
  const copyRows=copyFields.map(field=>`<button data-copy-value="${attr(field.value)}"><span>${esc(field.label)}</span><small>${esc(field.value)}</small></button>`).join("");
  const loadState=context?`${context.load_ms||0} ms`:`Loading saved Job Info…`;
  drawer.innerHTML=`
    <header class="drawer-head">
      <div><small class="drawer-kicker">${esc(job.division)} · ${esc(job.board)}</small><h2>${esc(job.client)}</h2><div class="drawer-meta">${esc(job.lane)} · ${job.days_in_lane} day(s) in lane</div></div>
      <div class="drawer-head-actions"><button class="client-link" data-client-page>Client page</button><button class="drawer-close job-drawer-close" data-drawer-close aria-label="Close job"><span aria-hidden="true">×</span><em>Close</em></button></div>
    </header>
    <div class="job-action-bar" aria-label="Job actions">
      <div class="action-cluster action-primary">
        <button class="job-action primary" data-add-update><i>＋</i>Field note</button>
        <details class="copy-menu"><summary class="job-action"><i>▣</i>Copy <span>⌄</span></summary><div class="copy-panel"><header><strong>Copy job details</strong><small>Uses the saved Job Info record</small></header>${copyRows}<button data-copy-summary><span>Job summary</span><small>All available details</small></button></div></details>
        <button class="job-action" data-job-action="photo_report"><i>▧</i>Photo report</button>
      </div>
      <div class="action-cluster action-destinations" aria-label="Open job in">
        <button class="job-action" data-job-action="folder"><i>▰</i>${context?.path?"Folder":"Find folder"}</button>
        ${job.url?`<button class="job-action destination" data-trello>${serviceIcon("trello")}Trello</button>`:""}
        <button class="job-action destination" data-job-action="xa">${serviceIcon("xa")}XA</button>
        <button class="job-action destination" data-job-action="companycam">${serviceIcon("companycam")}CompanyCam</button>
      </div>
    </div>
    <section class="update-composer" data-update-composer hidden></section>
    <div class="drawer-scroll">
      <section class="drawer-section"><div class="drawer-section-title"><h3>Operating status</h3><small>${esc(loadState)}</small></div><div class="drawer-facts">${fact("Division",job.division)}${fact("Current lane",job.lane)}${fact("Due",job.due?fmtDate(job.due):"Not scheduled")}${fact("Last activity",job.last_activity_at?fmtDate(job.last_activity_at):"—")}</div></section>
      ${context?renderProgress(progress,counts):`<section class="drawer-section context-loading"><i></i><div><strong>Loading job workspace</strong><small>Board details are ready; saved Job Info and requirements are loading.</small></div></section>`}
      ${context?renderJobInfo(fields):""}
      ${context?renderJobLog(context.job_log||[]):""}
    </div>`;
  drawer.hidden=false;
  $("[data-job-backdrop]").hidden=false;
  $("[data-client-page]",drawer).addEventListener("click",()=>{const accountName=job.account_client||job.client;closeDrawer();showView("clients");openClient(accountName);});
  $("[data-trello]",drawer)?.addEventListener("click",()=>desktopAction("open_url",context?.trello_url||job.url));
  $$('[data-job-action]',drawer).forEach(button=>button.addEventListener("click",()=>runJobAction(button.dataset.jobAction,button)));
  $("[data-add-update]",drawer).addEventListener("click",()=>showFieldNoteComposer(job));
  $$('[data-copy-value]',drawer).forEach(button=>button.addEventListener("click",()=>copyValue(button.dataset.copyValue,button)));
  $("[data-copy-summary]",drawer)?.addEventListener("click",()=>copyValue(copyFields.map(field=>`${field.label}: ${field.value}`).join("\n"),$("[data-copy-summary]",drawer)));
  bindRequirementActions(drawer);
  bindJobLogActions(drawer,job);
}
function renderProgress(progress,counts=progress.counts||{}){const items=progress.items||[],total=items.filter(item=>["mandatory","required"].includes(item.importance)).length,open=items.filter(item=>!["completed","not_applicable"].includes(item.status)),done=items.filter(item=>["completed","not_applicable"].includes(item.status));const rows=list=>list.map(requirementRow).join("");return `<section class="drawer-section requirements-section" data-requirements-section><div class="drawer-section-title"><div><h3>Requirements</h3><small>${esc(progress.stage_label||"")} · complete work here</small></div><strong>${progress.percent_complete??0}%</strong></div><div class="progress-track"><i style="width:${Math.max(0,Math.min(100,progress.percent_complete||0))}%"></i></div><div class="progress-meta"><span>${counts.todo||0} to do</span><span>${counts.blocked||0} blocked</span><span>${total} required</span></div>${items.length?`<div class="requirement-list">${rows(open)||`<p class="requirement-clear">All active requirements are handled.</p>`}</div>${done.length?`<details class="requirement-done"><summary>Completed or not needed <b>${done.length}</b></summary><div class="requirement-list">${rows(done)}</div></details>`:""}`:`<p class="muted">No requirements are active for this recorded job.</p>`}</section>`;}
function requirementRow(item){const handled=["completed","not_applicable"].includes(item.status),status=item.status==="not_applicable"?"Not needed":item.status==="in_progress"?"In progress":item.status==="blocked"?"Blocked":item.status==="completed"?"Complete":"To do";return `<article class="requirement-item req-${attr(item.status||"todo")}" data-requirement-item="${attr(item.key)}"><span class="requirement-state" aria-hidden="true">${item.status==="completed"?"✓":item.status==="not_applicable"?"—":item.status==="blocked"?"!":item.status==="in_progress"?"◐":"○"}</span><div><strong>${esc(item.label)}</strong><small>${esc(status)} · ${esc(item.owner||"Unassigned")}${item.evidence?` · Evidence: ${esc(item.evidence)}`:""}</small>${item.blocked_reason?`<p>${esc(item.blocked_reason)}</p>`:""}</div><div class="requirement-actions">${handled?"":`<button class="requirement-complete" data-requirement-complete="${attr(item.key)}">Complete</button>`}<button class="requirement-update" data-requirement-update="${attr(item.key)}">${handled?"Update":"More"}</button></div></article>`;}
function bindRequirementActions(root){if(!root)return;$$('[data-requirement-complete]',root).forEach(button=>button.addEventListener("click",()=>saveRequirement(button.dataset.requirementComplete,"completed","",{},button)));$$('[data-requirement-update]',root).forEach(button=>button.addEventListener("click",()=>openRequirementEditor(button.dataset.requirementUpdate)));}
