function renderJobLog(entries){return `<section class="drawer-section" data-job-log-section><div class="drawer-section-title job-log-title"><div><h3>Job log</h3><small>${entries.length} update${entries.length===1?"":"s"} · same history used by Snapshot</small></div><button class="quiet-button" data-import-trello-log>Import Trello</button></div><div class="job-log-preview">${entries.slice(0,8).map(entry=>`<article><header><div><strong>${esc(entry.work_type||"Job update")}</strong><time>${fmtDate(entry.work_date||entry.created_at)}</time></div>${entry.entry_id?`<button class="log-edit" data-edit-log="${attr(entry.entry_id)}">Edit</button>`:""}</header><p>${esc(entry.note||entry.status||"Saved update")}</p>${entry.technicians||entry.updated_by?`<small>${esc([entry.technicians,entry.updated_by].filter(Boolean).join(" · "))}</small>`:""}</article>`).join("")||`<p class="muted">No job-log updates yet. Add one here or import the recognized Trello notes.</p>`}</div></section>`;}
