async function importJobLog(job,button){const label=button.textContent;button.disabled=true;button.textContent="Importing…";try{const result=await transport("import_job_log",job.client,job.card_id||"");if(!result?.ok)throw new Error(result?.error||"Trello notes could not be imported");state.jobContext.job_log=result.job_log||state.jobContext.job_log||[];const current=$("[data-job-log-section]"),replacement=document.createElement("div");replacement.innerHTML=renderJobLog(state.jobContext.job_log);current?.replaceWith(replacement.firstElementChild);bindJobLogActions($("[data-job-log-section]"),job);toast(result.imported?`${result.imported} Trello update(s) imported`:"Job Log is up to date");}catch(error){toast(String(error instanceof Error?error.message:error));button.disabled=false;button.textContent=label;}}
async function loadJobContext(job){try{const result=await transport("job_context",job.client,job.card_id,job.division);if(state.selectedJob?.card_id!==job.card_id)return;if(!result?.ok)throw new Error(result?.error||"Job workspace unavailable");state.jobContext=result;renderJobDrawer(job,result);}catch(error){if(state.selectedJob?.card_id===job.card_id){state.jobContext={fields:[],job_log:[],progress:{},error:String(error)};renderJobDrawer(job,state.jobContext);toast(`Job details: ${error}`);}}}
async function showFieldNoteComposer(job){const host=$("[data-update-composer]");if(!host)return;host.hidden=false;host.classList.add("field-note-host");host.innerHTML=`<div class="field-note-loading"><i></i><span>Preparing field notes…</span></div>`;try{const division=job.division||"EMS",cacheKey=String(division).toUpperCase();let templates=state.fieldNoteTemplates[cacheKey];if(!templates){const result=await transport("field_note_templates",cacheKey);if(!result?.ok)throw new Error(result?.error||"Field notes are unavailable");templates=result.templates||[];state.fieldNoteTemplates[cacheKey]=templates;}if(!templates.length)throw new Error("No field-note templates are configured");renderFieldNoteForm(job,templates,templates[0].key);}catch(error){host.innerHTML=`<div class="composer-heading"><strong>Field notes unavailable</strong><small>${esc(error)}</small></div><button class="quiet-button" data-cancel-update>Close</button>`;$("[data-cancel-update]",host)?.addEventListener("click",()=>{host.hidden=true;host.classList.remove("field-note-host");});}}
function fieldInput(field){const common=`data-field-note-field="${attr(field.name)}" ${field.required?"required":""}`;if(field.type==="textarea")return `<textarea ${common} rows="${Number(field.rows)||2}" placeholder="${attr(field.placeholder||"")}">${esc(field.default||"")}</textarea>`;if(field.type==="select")return `<select ${common}>${(field.options||[]).map(option=>`<option value="${attr(option)}">${esc(String(option||"Choose…").replaceAll("_"," "))}</option>`).join("")}</select>`;return `<input ${common} type="${attr(field.type||"text")}" value="${attr(field.default||"")}" placeholder="${attr(field.placeholder||"")}">`;}
