async function saveFieldNote(job,template,host){const form=$("[data-field-note-form]",host),button=$("button[type='submit']",form),status=$("[data-update-status]",form),values={};$$('[data-field-note-field]',form).forEach(field=>values[field.dataset.fieldNoteField]=field.value);button.disabled=true;const prior=button.textContent;button.textContent="Saving…";status.textContent="";try{const sourceId=globalThis.crypto?.randomUUID?.()||`web-${Date.now()}-${Math.random().toString(16).slice(2)}`,result=await transport("save_field_note",job.client,template.key,values,job.division||"EMS",sourceId);if(!result?.ok)throw new Error(result?.error||"Could not save field note");if(!state.jobContext)state.jobContext={};state.jobContext.job_log=result.entries||[result.entry,...(state.jobContext.job_log||[])];replaceJobLog(job);host.hidden=true;host.classList.remove("field-note-host");toast(`${template.label} saved to Job Log`);}catch(error){button.disabled=false;button.textContent=prior;status.textContent=String(error instanceof Error?error.message:error);}}
function replaceJobLog(job){const current=$("[data-job-log-section]"),replacement=document.createElement("div");replacement.innerHTML=renderJobLog(state.jobContext?.job_log||[]);current?.replaceWith(replacement.firstElementChild);bindJobLogActions($("[data-job-log-section]"),job);}
function showUpdateComposer(job,existing=null){const host=$("[data-update-composer]");if(!host)return;const entry=existing||{},today=todayIso(),activity=entry.work_type||"Initial inspection",statusValue=entry.status||"completed";host._entry=entry;host.hidden=false;host.innerHTML=`<div class="composer-heading"><strong>${existing?"Edit job-log update":"Add job-log update"}</strong><small>${existing?"Changes keep a revision history":"This also feeds Snapshot"}</small></div><div class="composer-grid"><label>Date<input type="date" data-update-field="work_date" value="${attr(String(entry.work_date||today).slice(0,10))}"></label><label>Activity<select data-update-field="work_type">${["Initial inspection","Demo","Monitor","Equipment placed","Equipment pickup","Contents","Recon","Final inspection","Other"].map(value=>`<option ${value===activity?"selected":""}>${value}</option>`).join("")}</select></label><label>Status<select data-update-field="status">${["completed","scheduled","rescheduled","cancelled","skipped","needs_review"].map(value=>`<option value="${value}" ${value===statusValue?"selected":""}>${value.replaceAll("_"," ")}</option>`).join("")}</select></label><label>Crew<input data-update-field="technicians" value="${attr(entry.technicians||"")}" placeholder="Technician or crew"></label><label class="wide">Work completed / next step<textarea rows="3" data-update-field="note" placeholder="What happened, what was completed, and what comes next">${esc(entry.note||"")}</textarea></label></div><div class="composer-actions"><button class="primary-action" data-save-update>${existing?"Save changes":"Save update"}</button><button class="quiet-button" data-cancel-update>Cancel</button><span data-update-status></span></div>`;host.scrollIntoView({behavior:"smooth",block:"nearest"});$("[data-cancel-update]",host).addEventListener("click",()=>{host.hidden=true;host._entry=null;});$("[data-save-update]",host).addEventListener("click",()=>saveUpdate(job,host));}
async function saveUpdate(job,host){const button=$("[data-save-update]",host),status=$("[data-update-status]",host),entry={...(host._entry||{}),source:host._entry?.source||"pc"};$$('[data-update-field]',host).forEach(field=>entry[field.dataset.updateField]=field.value);button.disabled=true;const prior=button.textContent;button.textContent="Saving…";const result=await transport("save_job_update",job.client,entry);if(!result?.ok){button.disabled=false;button.textContent=prior;status.textContent=result?.error||"Could not save";return;}if(!state.jobContext)state.jobContext={};state.jobContext.job_log=result.entries||[result.entry,...(state.jobContext.job_log||[])];replaceJobLog(job);host.hidden=true;toast(host._entry?.entry_id?"Job Log changes saved":"Job Log updated");}
async function runJobAction(action,button){const job={...state.selectedJob,...(state.jobContext||{})};const label=button.innerHTML;button.disabled=true;button.textContent="Opening…";try{const result=await transport("job_action",action,job);if(!result?.ok)throw new Error(result?.error||"Action unavailable");toast(action==="photo_report"?"CompanyCam report workspace opened":"Opened");}catch(error){toast(String(error instanceof Error?error.message:error));}finally{button.disabled=false;button.innerHTML=label;}}
async function copyValue(value,button){if(!value)return;let ok=false;if(window.pywebview?.api?.copy_text){const result=await transport("copy_text",value);ok=Boolean(result?.ok);}else{try{await navigator.clipboard.writeText(value);ok=true;}catch(_){}}toast(ok?"Copied":"Could not copy");button.closest("details")?.removeAttribute("open");}
function closeDrawer(){state.selectedJob=null;state.jobContext=null;$("[data-job-drawer]").hidden=true;$("[data-job-backdrop]").hidden=true;}
function toggleTools(){const menu=$("[data-tools-menu]"),willOpen=menu.hidden;menu.hidden=!willOpen;$("[data-tools-toggle]").setAttribute("aria-expanded",String(willOpen));}
function closeTools(){$("[data-tools-menu]").hidden=true;$("[data-tools-toggle]").setAttribute("aria-expanded","false");}
async function launchTool(tool,button){closeTools();const label=button.innerHTML,pendingWindow=!window.pywebview?.api?window.open("","_blank"):null;button.disabled=true;try{const mode=await resolveTransport();if(mode==="browser"){let route=state.toolRoutes[tool]||state.data?.tool_routes?.[tool];if(!route){const routes=await transport("tool_routes");state.toolRoutes=routes?.routes||{};route=state.toolRoutes[tool];}if(!route)throw new Error("That browser tool is not available yet.");if(pendingWindow){try{pendingWindow.opener=null;pendingWindow.location.replace(route);}catch(_){pendingWindow.location.href=route;}toast("Tool opened in a browser tab");}else location.assign(route);return;}pendingWindow?.close();const result=await transport("launch_tool",tool);if(!result?.ok)throw new Error(result?.error||"Tool could not open");toast("Tool opened in its own window");}catch(error){pendingWindow?.close();toast(String(error instanceof Error?error.message:error));}finally{button.disabled=false;button.innerHTML=label;}}
async function desktopAction(method,arg){if(window.pywebview?.api?.[method])return window.pywebview.api[method](arg);if(method==="open_url")window.open(arg,"_blank","noopener");else toast("Folder access is available in the desktop app.");}
function tick(){$("[data-clock]").textContent=new Date().toLocaleTimeString([],{hour:"numeric",minute:"2-digit"});}
function setStatus(text,error=false){$("[data-status]").textContent=text;$("[data-status]").style.color=error?"var(--danger)":"";}
function toast(text){const el=$("[data-toast]");el.textContent=text;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3500);}
function fmtDate(v){if(!v)return"—";const d=new Date(`${String(v).slice(0,10)}T12:00:00`);return Number.isNaN(+d)?String(v):d.toLocaleDateString([],{month:"short",day:"numeric",year:"2-digit"});}
function fmtTime(v){const d=new Date(v);return Number.isNaN(+d)?"now":d.toLocaleTimeString([],{hour:"numeric",minute:"2-digit"});}
function todayIso(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;}
function initials(v){return String(v||"?").split(/[\s,()-]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase();}
function shortBoard(v){return String(v||"").replace("WORK IN PROGRESS","Work in progress").replace("ESTIMATING","Estimating").replace("CONTENTS","Contents");}
function shortDivision(v){return v==="CONTENTS"?"Contents":v==="RECON"?"Recon":"EMS";}
